@@ -608,6 +608,24 @@ func (r *SearchFieldsRegistry) For(key LowerGroupResource) (selectableFields []s
 	return r.selectableFields[key], r.searchFieldsHashes[key], r.searchFieldsProvider[key]
 }

+// HasSelectableFields reports whether the kind declares every one of the given
+// fields as selectable, so the index holds all of them. It is false for an empty
+// field list and for a kind the registry does not know.
+func (r *SearchFieldsRegistry) HasSelectableFields(key LowerGroupResource, fields ...string) bool {
+	if len(fields) == 0 {
+		return false
+	}
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	declared := r.selectableFields[key]
+	for _, f := range fields {
+		if !slices.Contains(declared, f) {
+			return false
+		}
+	}
+	return true
+}
